  MigrationChecks.Assert(sample.Life.Souls.Any(s=>ExpeditionGame.IsMelee(s.Weapon))&&sample.Life.Souls.Any(s=>ExpeditionGame.IsBow(s.Weapon))&&sample.Life.Souls.Any(s=>ExpeditionGame.IsGun(s.Weapon)),"Weapon table contains all three combat classes");
