  string brood=$"boss/campaign/{game.Save.Seed}/2/mega/992/1";AddEnemy(brood,0,-9,5);boss=infected.Single(e=>e.Id==brood);TickMega(boss,.01);MigrationChecks.Assert(infected.Count(e=>IsMegaNest(e.Id))==3,"Matriarch creates three physical destroyable nests");boss.BossStep=1;MegaWave(boss);int full=infected.Count(e=>e.Id.StartsWith(brood+"/wave/"));KillEnemy(infected.First(e=>IsMegaNest(e.Id)));foreach(var e in infected.Where(e=>e.Id.StartsWith(brood+"/wave/")).ToArray())RemoveEnemy(e);boss.BossStep=2;MegaWave(boss);MigrationChecks.Assert(infected.Count(e=>e.Id.StartsWith(brood+"/wave/"))<full,"Destroying nests reduces actual subsequent wave size");ClearMegaChildren(boss);ClearEnemies();
  string iron=$"boss/campaign/{game.Save.Seed}/2/mega/993/2";AddEnemy(iron,0,-9,5);boss=infected.Single(e=>e.Id==iron);boss.BossState="volley";boss.BossTime=1;boss.BossAim=player.Position;boss.Cooldown=0;TickMega(boss,.01);MigrationChecks.Assert(megaProjectiles.Count==3,"Mourner fires actual moving projectiles");ClearMegaChildren(boss);MigrationChecks.Assert(megaProjectiles.Count==0,"Encounter cleanup removes live projectiles");ClearEnemies();
  player.Position=new(0,.1f,0);game.Shield=0;game.Life.Health=game.MaxHealth;await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);
  double hp=game.Life.Health;AddMegaProjectile(iron,new(0,1.1f,-5),Vector3.Back*18);TickMegaProjectiles(.3);MigrationChecks.Assert(game.Life.Health<hp,"Moving boss projectile damages a real player collider");
