  var previousGame=game;var previousRoom=dungeon;var previousPosition=player.Position;
  try{game=sample;dungeon=null;player.Position=Ground(0,12);Community.Established=true;Community.X=0;Community.Z=12;Community.Food=12;Community.Water=12;game.World.Changes.CampModules.Clear();var station=new BuildPiece{Health=100,Kind=Array.FindIndex(BuildDefinition.All,d=>d.Function=="water"),X=2,Z=12,Y=game.World.Height(2,12)};game.Building.Pieces.Add(station);
   MegaGearAction("install/"+module.Id);MigrationChecks.Assert(game.World.Changes.CampModules.Count==1,"Camp install validates actual location and station");int food=Community.Food;TickCampModules(1);MigrationChecks.Assert(Community.Food==food-module.Upkeep&&game.ModulePower(0)>0&&CampProduction(station)>1,"Upkeep pays from real camp stores and production gets module multiplier");
   Community.Food=0;game.World.Changes.CampModules[0].Charge=.1;TickCampModules(1);MigrationChecks.Assert(game.ModulePower(0)==0&&CampProduction(station)==1,"Unfunded module stops actual production bonus");
  }finally{game=previousGame;dungeon=previousRoom;player.Position=previousPosition;}
  GD.Print("PASS / specialist mega tables, three weapon classes, four armor slots, research gates, three module slots, upkeep state, portable loot, breakable shell, physical nests/reduced waves and projectile volley");
 }
}
